            if len(panLinkInfoList) > 0 {
                linkInfo := panLinkInfoList[0]
                if linkInfo.DisplayName == "该分享文件已过期" || linkInfo.FileSuffix == "无法访问" {
					fmt.Println("kkkkkkkkkkk")
                    return fmt.Errorf("invalid resource status, short link: %s", shortURL)
