//	error: 操作过程中发生的错误，成功时为 nil
func (a *BacktrackPanLinkInfo) ExportPanLinkInfo(ctx context.Context) (string, error) {
	condition := map[string]any{
		"link_status": 1, // -1:invalid, 0:unchecked
		//"backtrack_status": 0,
	}
	// 捞取7天前的数据，避免跟任务starlink_get_qa_for_link冲突
	if a.StartTimeDiff > 0 {
		a.EndTime = time.Now().Unix() - a.StartTimeDiff
	}
	createTimeCondition := map[string]any{}
	if a.StartTime != 0 {
		createTimeCondition["$gte"] = a.StartTime
	}
	if a.EndTime != 0 {
		createTimeCondition["$lte"] = a.EndTime
	}
	if len(createTimeCondition) > 0 {
		condition["create_time"] = createTimeCondition
	}

	conf := &exporter.ExportConf{
		Env:       exporter.OnlineEnv,
		Name:      mongoEntities.CollectionPanLinkInfo,
		ExportDir: exportDir,
		Filter:    condition,
		Fields:    []string{"short_url"},
		Server: exporter.Server{
			Name:     mongoEntities.CollectionPanLinkInfo,
			Hostname: "mongos-rdata.www.yq01.serv",
		},
	}
	m := exporter.NewMongoExporter(logit.NewSimple(os.Stdout))
	err := m.Run(ctx, conf)
	if err != nil {
		return "", err
	}
	//读取文件进行 数据判断
	fileName, err := exporter.GetFileName(conf.ExportDir, conf.Name, exporter.MongoExportPrefix)
	if err != nil {
		return "", err
	}
	return fileName, nil
}

